        snprintf(key, sizeof(key), "%ld", id);
        push_notify(src, key, summary);
        n_new++;

        last_max = id;  /* id > last_max guaranteed by the continue above */
    }

    if (n_new > 0) {
        snprintf(s_cfg[src].last_cursor, sizeof(s_cfg[src].last_cursor),
                 "%ld", last_max);
        persist_cursor(src);
    }

    cJSON_Delete(root);
    *n_new_out = n_new;
